const D = { energy:.6, scale:1, density:.5, speed:1, hue:32, x:.5, y:.5, paradox:.8, style:'concrete', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'lithograph'), neon = (sty === 'neon'), dk = (sty === 'chiaroscuro');

const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.44 + .56*P.energy) * (.55 + .5*K.intensity) + bsm*.26;
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

// ---- AXONOMETRIC, not perspective: parallel projection is what makes depth
//      ambiguous, and the paradox is a deliberate painter's-order violation.
//      The azimuth turns forever on incommensurate rates -> never the same pose.
const az = .105*K.t*P.speed + .42*Math.sin(K.t*.037) + .18*Math.sin(K.t*.091+1.3);
const sa2 = Math.sin(az), ca2 = Math.cos(az);
const ELEV = .50 + .13*Math.sin(K.t*.071) + .05*Math.sin(K.t*.163+2.1);
const SC = u*.50*P.scale;
const ox = cl(P.x,.15,.85)*width, oy = cl(P.y,.2,.8)*height + u*.02*dC*P.energy;
const NFR = 3 + Math.round(cl(P.density,0,1)*4);
const PDX = cl(P.paradox,0,1);

function pj(X,Y,Z){ return [ox + (X*ca2 - Z*sa2)*SC, oy + ((X*sa2 + Z*ca2)*ELEV + Y)*SC]; }
const dep = (X,Z) => X*sa2 + Z*ca2;

// ---- tone tables ---------------------------------------------------------------
function tone(v, tv){
  if (paper) return [40, 5 + 5*tv, cl(96 - 62*(1-v), 26, 96)];
  if (wire)  return [212, cl(64 - 24*v, 10, 70), cl(13 + 16*v, 8, 40)];
  if (dk)    return [HU, cl(22 - 12*v, 0, 26), cl(2 + 92*Math.pow(v,1.9), 1, 97)];
  if (neon)  return [(HU + 150 + 120*v)%360, cl(78 - 30*v, 20, 90), cl(10 + 76*v, 6, 96)];
  return [(HU + 14 - 10*v)%360, cl(24 - 12*v + 6*tv, 3, 34), cl(10 + 76*v, 5, 95)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a);
  else if (paper) stroke(30, 24, 10, a);
  else if (neon) stroke((HU+180)%360, 40, 100, a*.7);
  else stroke((HU+10)%360, 10, 6, a*.8);
}

// ---- ground: a graded void, banded (never a flat fill) --------------------------
noStroke();
const NBD = 32;
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1);
  let c;
  if (paper)     c = [40, 4 + 4*s, 95 - 9*s];
  else if (wire) c = [214, 64, 10 + 8*s];
  else if (neon) c = [(HU+200)%360, 62 - 20*s, 5 + 9*s];
  else if (dk)   c = [HU, 14, 3 + 6*s];
  else           c = [(HU + 196 - 30*s)%360, 26 - 8*s, 9 + 17*Math.pow(s,1.4)];
  fill(c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.6, 0, 100));
  rect(0, s*height - 1.5, width, height/NBD + 3);
}

// ---- build the lattice: cuboid bar-frames, seeded, each bobbing on its own rate --
const EDG = [];
for (let a=0;a<3;a++) for (let s1=-1;s1<=1;s1+=2) for (let s2=-1;s2<=1;s2+=2) EDG.push([a,s1,s2]);

const bars = [];
for (let fi=0; fi<NFR; fi++){
  const h = .17 + .16*fr(fi*5.3+1);
  const w = h*(.15 + .07*fr(fi*9.1));
  const cx = (fr(fi*3.1)-.5)*1.05, cz = (fr(fi*11.3)-.5)*1.05;
  const cy = (fr(fi*7.7)-.5)*.72 + .075*Math.sin(K.t*(.23 + fr(fi*2.3)*.47) + fi*1.9)
           + .045*Math.sin(K.t*(.61 + fr(fi*4.7)*.33) + fi*.7);
  const ctr = [cx, cy, cz];
  for (let e=0; e<12; e++){
    const ax = EDG[e][0], s1 = EDG[e][1], s2 = EDG[e][2];
    const o1 = (ax+1)%3, o2 = (ax+2)%3;
    const lo = [0,0,0], hi = [0,0,0];
    lo[ax] = ctr[ax] - h - w; hi[ax] = ctr[ax] + h + w;
    lo[o1] = ctr[o1] + s1*h - w; hi[o1] = ctr[o1] + s1*h + w;
    lo[o2] = ctr[o2] + s2*h - w; hi[o2] = ctr[o2] + s2*h + w;
    const mx = (lo[0]+hi[0])*.5, mz = (lo[2]+hi[2])*.5;
    bars.push([dep(mx,mz), lo, hi, fi, fr(fi*31.7 + e*3.3)]);
  }
}
bars.sort((a,b) => a[0]-b[0]);                 // far -> near
const NB = Math.min(bars.length, 42);
const keep = bars.slice(bars.length-NB);       // the nearest NB bars

// per frame, remember its FARTHEST bar — redrawing that on top is the paradox
const liar = {};
for (let i=0;i<keep.length;i++){ const b = keep[i]; if (liar[b[3]] === undefined) liar[b[3]] = i; }

strokeWeight(Math.max(1, u*.0016));
function bx(b){
  const lo = b[1], hi = b[2], tv = b[4];
  const hz = cl(.5 - b[0]*.5, 0, 1);                       // farther => flatter/hazier
  const x = sa2 >= 0 ? hi[0] : lo[0];
  const z = ca2 >= 0 ? hi[2] : lo[2];
  const faces = [
    [ [lo[0],lo[1],lo[2], hi[0],lo[1],lo[2], hi[0],lo[1],hi[2], lo[0],lo[1],hi[2]], .92 ],
    [ [x,lo[1],lo[2], x,hi[1],lo[2], x,hi[1],hi[2], x,lo[1],hi[2]], .22 + .50*Math.abs(sa2) ],
    [ [lo[0],lo[1],z, hi[0],lo[1],z, hi[0],hi[1],z, lo[0],hi[1],z], .22 + .50*Math.abs(ca2) ]
  ];
  for (let q=0;q<3;q++){
    const v = cl(faces[q][1]*(.55+.5*gl)*(.90+.18*tv) - .10*hz, 0, 1);
    const c = tone(v, tv);
    if (wire) noFill(); else { fill(c[0], c[1], c[2], 100); }
    ink(paper ? 62 : wire ? 62 : 40);
    const g2 = faces[q][0];
    beginShape();
    for (let i=0;i<4;i++){ const p = pj(g2[i*3], g2[i*3+1], g2[i*3+2]); vertex(p[0], p[1]); }
    endShape(CLOSE);
  }
  // engraved hatching on the dark faces — texture, never a flat fill
  if (paper){
    const g2 = faces[Math.abs(sa2) < Math.abs(ca2) ? 1 : 2][0];
    ink(30); strokeWeight(Math.max(1, u*.0010));
    for (let i=1;i<=4;i++){
      const t2 = i/5;
      const p0 = pj(g2[0]+(g2[3]-g2[0])*t2, g2[1]+(g2[4]-g2[1])*t2, g2[2]+(g2[5]-g2[2])*t2);
      const p1 = pj(g2[9]+(g2[6]-g2[9])*t2, g2[10]+(g2[7]-g2[10])*t2, g2[11]+(g2[8]-g2[11])*t2);
      line(p0[0], p0[1], p1[0], p1[1]);
    }
    strokeWeight(Math.max(1, u*.0016));
  }
  if (neon){
    push(); blendMode(ADD); noStroke();
    const g2 = faces[0][0];
    fill((HU+170)%360, 40, 100, cl(5 + 10*gl, 0, 20));
    beginShape();
    for (let i=0;i<4;i++){ const p = pj(g2[i*3], g2[i*3+1], g2[i*3+2]); vertex(p[0], p[1]); }
    endShape(CLOSE);
    pop(); blendMode(BLEND);
  }
}

// ---- pass 1: honest painter's order, far -> near ---------------------------------
for (let i=0;i<keep.length;i++) bx(keep[i]);

// ---- pass 2: THE LIE. Each frame's farthest strut is repainted on top, so it
//      passes in front of the strut it just went behind. Cyclic occlusion =
//      the figure reads as solid and as impossible at the same time.
if (PDX > .02){
  for (const k2 in liar){
    if (fr((k2|0)*17.3 + 5) > PDX) continue;
    bx(keep[liar[k2]]);
  }
}

// ---- stair treads climbing the nearest frames — the Relativity read ---------------
const NST = Math.min(3, NFR);
for (let fi=0; fi<NST; fi++){
  if (fr(fi*23.1+7) > .62) continue;
  const h = .17 + .16*fr(fi*5.3+1);
  const cx = (fr(fi*3.1)-.5)*1.05, cz = (fr(fi*11.3)-.5)*1.05;
  const cy = (fr(fi*7.7)-.5)*.72 + .075*Math.sin(K.t*(.23 + fr(fi*2.3)*.47) + fi*1.9)
           + .045*Math.sin(K.t*(.61 + fr(fi*4.7)*.33) + fi*.7);
  const nt = 5, tw = h*.30, th2 = (2*h)/nt;
  const along = (fr(fi*13.7) < .5) ? 0 : 2;
  for (let s2=0; s2<nt; s2++){
    const t2 = -h + (s2+.5)*th2;
    const lo = [0,0,0], hi = [0,0,0];
    if (along === 0){ lo[0] = cx + t2 - th2*.5; hi[0] = cx + t2 + th2*.5; lo[2] = cz + h - tw; hi[2] = cz + h + tw; }
    else            { lo[2] = cz + t2 - th2*.5; hi[2] = cz + t2 + th2*.5; lo[0] = cx + h - tw; hi[0] = cx + h + tw; }
    // the tread climbs as it goes — and RESETS at the far end, which is the same
    // lie the Penrose staircase tells: a periodic run pretending to be monotone
    const ry = cy + h - (s2/nt)*2*h*.86;
    lo[1] = ry; hi[1] = ry + th2*.55;
    const mx = (lo[0]+hi[0])*.5, mz = (lo[2]+hi[2])*.5;
    bx([dep(mx,mz), lo, hi, fi, fr(fi*7.1+s2*2.9)]);
  }
}

// ---- cached grain + vignette ------------------------------------------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9000, Math.floor(width*height/240));
  for (let i=0;i<N;i++){
    const px = Math.abs((Math.sin(i*12.9898)*43758.5453)%1)*width;
    const py = Math.abs((Math.sin(i*78.233+2.1)*43758.5453)%1)*height;
    g.fill(0,0, (i%2) ? 100 : 0, paper ? 9 : 5);
    g.rect(px, py, 1.7, 1.7);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.085;
    g.fill(0,0,0, 1.0 + 3.4*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
